class Solution {
    public String smallestNumber(String pattern){
        StringBuilder answer=new StringBuilder();
        Deque<Integer> stack=new ArrayDeque<>();
        for(int i=0;i<=pattern.length();i++){
            stack.push(i+1);
            if(i==pattern.length()||pattern.charAt(i)=='I')while(!stack.isEmpty())answer.append(stack.pop());
        }
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun smallestNumber(pattern:String):String{
        val answer=StringBuilder();
        val stack=java.util.ArrayDeque<Int>();
        for(i in 0..pattern.length){
            stack.push(i+1);
            if(i==pattern.length||pattern[i]=='I')while(stack.isNotEmpty())answer.append(stack.pop())
        };
        return answer.toString()
    }
}

